// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, c.MinSum(), 1 ether + amount % 1 ether);

        address actor = address(0x1234);
        vm.deal(actor, amount + c.MinSum());

        uint256 deposit = amount + 1;
        vm.prank(actor);
        c.Put{value: deposit}(0);

        vm.warp(block.timestamp + 1);

        uint256 balBefore = __invmut_c_Acc_balance(actor);

        vm.prank(actor);
        c.Collect(amount);

        uint256 balAfter = __invmut_c_Acc_balance(actor);

        assertTrue(balAfter == balBefore - amount);
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
